UPDATE runtime_delivery_units SET status='sent',message_ids=?6,updated_at=CAST(unixepoch('subsec') * 1000000 AS INTEGER) WHERE operation_id=?1 AND attempt=?2 AND ordinal=?5 AND status='sending' AND json_valid(?6) AND json_type(?6)='array' AND json_array_length(?6)=artifact_count AND (SELECT count(DISTINCT value) FROM json_each(?6))=artifact_count AND NOT EXISTS(SELECT 1 FROM json_each(?6) WHERE type<>'integer' OR value<=0 OR value>2147483647) AND EXISTS(SELECT 1 FROM runtime_operations o WHERE o.id=?1 AND o.attempt=?2 AND o.lease_token=?3 AND o.worker_id=?4 AND o.status='delivering' AND o.lease_expires_at>CAST(unixepoch('subsec') * 1000000 AS INTEGER));